operation.add:
if (!class_exists('Mobile_Detect')) {
require_once(DIR_SYSTEM . 'Mobile_Detect.php');
}
$wdh_mobile_detect = new Mobile_Detect;
$wdh_is_mobile = (!$wdh_mobile_detect->isTablet() && $wdh_mobile_detect->isMobile());
		$wdh_product_image_width = $wdh_is_mobile ? 180 : $this->config->get('theme_' . $this->config->get('config_theme') . '_image_product_width');
$wdh_product_image_height = $wdh_is_mobile ? 180 : $this->config->get('theme_' . $this->config->get('config_theme') . '_image_product_height');
if ($wdh_is_mobile) {
    $wdh_img_effect_config = $this->config->get('module_ptcontrolpanel_img_effect');
    if (is_array($wdh_img_effect_config)) {
        $wdh_img_effect_config[$this->config->get('config_store_id')] = false;
        $this->config->set('module_ptcontrolpanel_img_effect', $wdh_img_effect_config);
    }
}

